#!/usr/bin/env python3
"""Compute the CSX-147_Q1 score-ledger ground truth from local event files."""

from __future__ import annotations

import csv
import datetime as dt
import html
import json
import re
from pathlib import Path
from typing import Any
from urllib.parse import parse_qs, urlparse


TASK_ID = "CSX-147_Q1"
EVENT_ID = "CSX-147"
TARGET_FAMILY = "bangladesh_2004_storm_flood_process_score_ledger"
TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
EVENT_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

ANCHOR_JSON = "data/event_reports/event_reports_004_Locked_event_anchor_April_2004_Bangladesh_severe_storms_and_floods.json"
ARTICLE_HTML = "data/other/other_001_NASA_Earth_Observatory_Bangladesh_flood_follow-up_image.html"


def load_json(rel_path: str) -> Any:
    with (EVENT_DIR / rel_path).open("r", encoding="utf-8-sig") as handle:
        return json.load(handle)


def read_text(rel_path: str) -> str:
    return (EVENT_DIR / rel_path).read_text(encoding="utf-8", errors="ignore")


def clean_html_text(text: str) -> str:
    text = re.sub(r"<script[\s\S]*?</script>", " ", text, flags=re.I)
    text = re.sub(r"<style[\s\S]*?</style>", " ", text, flags=re.I)
    text = re.sub(r"<[^>]+>", " ", text)
    return re.sub(r"\s+", " ", html.unescape(text)).strip()


def inclusive_days(start: str, end: str) -> int:
    return (dt.date.fromisoformat(end) - dt.date.fromisoformat(start)).days + 1


def day_lag(start: str, end: str) -> int:
    return (dt.date.fromisoformat(end) - dt.date.fromisoformat(start)).days


def article_text() -> str:
    raw = read_text(ARTICLE_HTML)
    paragraphs = re.findall(r"<p>(.*?)</p>", raw, flags=re.I | re.S)
    return " ".join(clean_html_text(paragraph) for paragraph in paragraphs)


def remote_event_snapshot_date() -> str:
    with (EVENT_DIR / "metadata" / "files.csv").open(newline="", encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            if row.get("source_name") != "event":
                continue
            query = parse_qs(urlparse(row["url"]).query)
            return query["TIME"][0]
    raise ValueError("event snapshot row not found")


def first_int(pattern: str, text: str, label: str) -> int:
    match = re.search(pattern, text, flags=re.I)
    if not match:
        raise ValueError(f"missing {label}")
    return int(match.group(1))


def build_ground_truth() -> dict[str, Any]:
    event = load_json("metadata/event.json")
    anchor = load_json(ANCHOR_JSON)
    text = article_text()

    event_start = anchor["temporal_window"]["start_date"]
    event_end = anchor["temporal_window"]["end_date"]
    event_days = inclusive_days(event_start, event_end)

    storm_match = re.search(r"began on April ([0-9]+) and lasted through April ([0-9]+)", text, flags=re.I)
    if not storm_match:
        raise ValueError("missing storm sequence")
    storm_start = f"2004-04-{int(storm_match.group(1)):02d}"
    storm_end = f"2004-04-{int(storm_match.group(2)):02d}"
    storm_days = inclusive_days(storm_start, storm_end)
    storm_window_coverage_ratio = round(storm_days / event_days, 3)

    intense_thunderstorms_text = bool(re.search(r"series of intense thunderstorms", text, flags=re.I))
    floods_followed_storms_text = bool(re.search(r"floods followed on the heels", text, flags=re.I))
    upland_runoff_cause_text = bool(re.search(r"caused by water rushing out of the Khasi Hills", text, flags=re.I))
    displacement = 500000 if re.search(r"half a million people in Bangladesh", text, flags=re.I) else 0
    khasi_hills_text = bool(re.search(r"Khasi Hills", text, flags=re.I))
    border_text = bool(re.search(r"border between India and Bangladesh", text, flags=re.I))
    image_day = first_int(r"On April ([0-9]+), 2004, the clouds cleared", text, "image date")
    image_date = f"2004-04-{image_day:02d}"
    resolution = first_int(r"resolution of ([0-9]+) meters per pixel", text, "resolution")
    event_snapshot_date = remote_event_snapshot_date()

    tests = {
        "sequence_persistence": {
            "pass": storm_days >= 10 and storm_window_coverage_ratio >= 0.75,
            "values": {
                "storm_start": storm_start,
                "storm_end": storm_end,
                "storm_days": storm_days,
                "event_days": event_days,
                "storm_window_coverage_ratio": storm_window_coverage_ratio,
            },
        },
        "storm_flood_causation_text": {
            "pass": intense_thunderstorms_text and floods_followed_storms_text and upland_runoff_cause_text,
            "values": {
                "intense_thunderstorms_text": intense_thunderstorms_text,
                "floods_followed_storms_text": floods_followed_storms_text,
                "upland_runoff_cause_text": upland_runoff_cause_text,
            },
        },
        "displacement_anchor": {
            "pass": displacement >= 400000,
            "values": {
                "reported_displaced_people": displacement,
            },
        },
        "terrain_text": {
            "pass": khasi_hills_text and border_text,
            "values": {
                "khasi_hills_text": khasi_hills_text,
                "india_bangladesh_border_text": border_text,
            },
        },
        "image_timing": {
            "pass": day_lag(storm_end, image_date) > 0 and day_lag(event_end, image_date) <= 7 and resolution == 250,
            "values": {
                "image_date": image_date,
                "event_snapshot_date": event_snapshot_date,
                "lag_after_storm_end_days": day_lag(storm_end, image_date),
                "lag_after_event_end_days": day_lag(event_end, image_date),
                "resolution_m_per_pixel": resolution,
            },
        },
    }
    score = sum(1 for test in tests.values() if test["pass"])
    answer = "multi_day_storm_flood_process_ledger_pass" if score == 5 else "storm_flood_process_ledger_incomplete"
    rejected = ["single_day_storm", "storm_unlinked_flood_case", "snapshot_timing_label"]
    interpretation = (
        "The ledger supports a multi-day storm-flood process because an 11-day storm sequence is text-linked "
        "to upland runoff, cross-border flooding, 500000 displaced people, and a timely 250 m follow-up image."
    )

    rubric = [
        {
            "name": "Final ledger and answer",
            "points": 3,
            "description": "Reports target_family, all five true tests, score 5, answer multi_day_storm_flood_process_ledger_pass, and the three rejected alternatives.",
            "partial_credit": "Give 1-2 points if the answer label is close but one test status, the score, or one rejected alternative is missing.",
        },
        {
            "name": "Sequence arithmetic",
            "points": 3,
            "description": "Computes 11 storm days, 14 event days, 0.786 coverage ratio, and applies the 10-day and 0.75 thresholds correctly.",
            "partial_credit": "Give 1-2 points for correct dates but one missing inclusive-day or ratio calculation.",
        },
        {
            "name": "Storm-flood causation text",
            "points": 4,
            "description": "Finds the series of intense thunderstorms, the statement that floods followed that sequence, and the upland runoff cause text.",
            "partial_credit": "Give 2-3 points for two correct causal text anchors; give 1 point for only one anchor.",
        },
        {
            "name": "Displacement extraction",
            "points": 3,
            "description": "Extracts about half a million displaced people in Bangladesh as 500000 and applies the >=400000 test.",
            "partial_credit": "Give 1-2 points for a correct qualitative half-million reading without the numeric threshold.",
        },
        {
            "name": "Terrain text anchors",
            "points": 2,
            "description": "Finds both the Khasi Hills and India-Bangladesh border area text anchors.",
            "partial_credit": "Give 1 point for naming only one of the two anchors.",
        },
        {
            "name": "Image timing and resolution",
            "points": 3,
            "description": "Computes 2004-04-26, 7 days after storm end, 4 days after event end, 250 m per pixel, and the true pass state.",
            "partial_credit": "Give 1-2 points for the correct image date and resolution but one missing lag calculation.",
        },
        {
            "name": "Compact computed interpretation",
            "points": 2,
            "description": "Keeps the interpretation tied to the five calculations and avoids extra loss counts beyond the ledger.",
            "partial_credit": "Give 1 point if the interpretation is broadly consistent but weakly tied to the computed values.",
        },
    ]

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "target_family": TARGET_FAMILY,
        "primary_gt": {
            "target_family": TARGET_FAMILY,
            "tests": tests,
            "score": score,
            "answer": answer,
            "rejected_alternatives": rejected,
            "interpretation": interpretation,
        },
        "numeric_tolerances": {
            "ratio": 0.001,
            "days": 0,
            "people": 0,
        },
        "key_values": {
            "event_name": event.get("event_name", "April 2004 Bangladesh severe storms and floods"),
            "event_window": {"start": event_start, "end": event_end, "days": event_days},
            "storm_sequence": {"start": storm_start, "end": storm_end, "days": storm_days},
            "tests": tests,
            "rejected_alternatives": rejected,
        },
        "rubric": {"total_points": 20, "criteria": rubric},
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                "metadata/event.json",
                "metadata/files.csv",
                ANCHOR_JSON,
                ARTICLE_HTML,
            ],
            "notes": [
                "Off-event gridded precipitation products are not used in this ground truth.",
                "The scored evidence comes from the declared event anchor, NASA Earth Observatory text, and package metadata.",
            ],
        },
    }


def main() -> None:
    output = TASK_DIR / "computed_gt.json"
    output.write_text(json.dumps(build_ground_truth(), indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
